export function journeyText(language, key, replacements = {}) {
  const extra = {
    en: { reached: 'Value reached — confirming', missingWindow: 'Average unavailable: {count} dates are missing from the last five days.' },
    de: { reached: 'Wert erreicht — Bestätigung läuft', missingWindow: 'Durchschnitt nicht verfügbar: In den letzten fünf Tagen fehlen {count} Daten.' },
    es: { reached: 'Valor alcanzado — confirmando', missingWindow: 'Promedio no disponible: faltan {count} fechas en los últimos cinco días.' },
    fr: { reached: 'Valeur atteinte — confirmation en cours', missingWindow: 'Moyenne indisponible : il manque {count} dates dans les cinq derniers jours.' },
  }
  return (extra[language][key] ?? values[language][keys.indexOf(key)]).replace(/\{(\w+)\}/g, (_, name) => replacements[name] ?? '')
}
